def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    H, W = g.shape
    steps = ((0, 1), (1, 0), (0, -1), (-1, 0))

    def inb(p):
        return 0 <= p[0] < H and 0 <= p[1] < W

    for comp in components(g == 3):
        cs = set(comp)
        # head: a 3 cell with 0 on both opposite sides (0 3 0 marker)
        heads = []
        for (y, x) in comp:
            for dy, dx in ((0, 1), (1, 0)):
                a, b = (y - dy, x - dx), (y + dy, x + dx)
                if inb(a) and inb(b) and g[a] == 0 and g[b] == 0:
                    heads.append((y, x))
        if not heads:
            continue
        # tail marker: a 5 touching the snake
        fives = {(y + dy, x + dx) for (y, x) in comp for dy, dx in steps
                 if inb((y + dy, x + dx)) and g[y + dy, x + dx] == 5}
        if not fives:
            continue
        h = heads[0]
        first = [(h[0] + dy, h[1] + dx) for dy, dx in steps if (h[0] + dy, h[1] + dx) in cs]
        if not first:
            continue
        # retract: erase body, remove tail 5, place 5 right after the head
        for c in comp:
            if c != h:
                g[c] = bg
        for f in fives:
            g[f] = bg
        g[first[0]] = 5
        emit(g, f"Snake with head at {h} has a 5 at its tail: erase its body, drop the tail 5, and put the 5 next to the head at {first[0]}")

    emit(g, "All marked snakes retracted into their heads; unmarked snakes unchanged")
    return g
